def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    border = []
    border += grid[0] + grid[-1]
    border += [grid[r][0] for r in range(1, h - 1)]
    border += [grid[r][-1] for r in range(1, h - 1)]
    marker = Counter(v for v in border if v != bg).most_common(1)[0][0]

    seeds = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, marker)]
    if not seeds:
        return [row[:] for row in grid]
    seed_color = grid[seeds[0][0]][seeds[0][1]]

    # Gather contiguous marker segments on each boundary.
    def runs(values):
        result = []
        start = None
        for i, value in enumerate(values + [None]):
            if value == marker and start is None:
                start = i
            elif value != marker and start is not None:
                result.append((start, i - 1))
                start = None
        return result

    horizontal_edges = []
    for side, row in (("top", grid[0]), ("bottom", grid[-1])):
        horizontal_edges.extend((side, a, b) for a, b in runs(row))

    vertical_edges = []
    for side, values in (("left", [grid[r][0] for r in range(h)]),
                         ("right", [grid[r][-1] for r in range(h)])):
        vertical_edges.extend((side, a, b) for a, b in runs(values))

    use_horizontal_edges = sum(b - a + 1 for _, a, b in horizontal_edges) >= \
                           sum(b - a + 1 for _, a, b in vertical_edges)
    edges = horizontal_edges if use_horizontal_edges else vertical_edges
    if not edges:
        return [row[:] for row in grid]

    # The nearest edge segment supplies the reference position for the seed pattern.
    coords = [c if use_horizontal_edges else r for r, c in seeds]

    def segment_distance(seg, q):
        _, a, b = seg
        return max(a - q, 0, q - b)

    ref = min(edges, key=lambda seg: sum(segment_distance(seg, q) for q in coords))
    ref_start = ref[1]

    out = [row[:] for row in grid]
    original = grid

    for side, a, b in edges:
        for q in coords:
            pos = a + (q - ref_start)
            if not 0 <= pos < (w if use_horizontal_edges else h):
                continue

            if use_horizontal_edges:
                if side == "top":
                    cells = [(r, pos) for r in range(1, h)]
                else:
                    cells = [(r, pos) for r in range(h - 2, -1, -1)]
            else:
                if side == "left":
                    cells = [(pos, c) for c in range(1, w)]
                else:
                    cells = [(pos, c) for c in range(w - 2, -1, -1)]

            for r, c in cells:
                if original[r][c] == marker:
                    continue
                if original[r][c] == seed_color:
                    out[r][c] = 4
                    break
                out[r][c] = seed_color

    return out
